// v16.xx (coop9), HIS ORDER (2026-10-14), the two player first: THE POWER-UPS ARE SHARED. Each window rolled the drops for its own kills and kept its own pickups, so a coin that dropped for player 1 was
// only ever on player 1 screen: player 2 could not see it, never mind take it. A drop is now told to the other window over the pair channel the team combo already uses (t arcpw, op new: a
// name for the pickup that is the same in both windows, what it is and where it lies), which puts the same pickup on the floor there; whoever walks over it first takes it for himself (the
// effect, the timer chip and the note are his own) and tells the other window (op take), which takes it off the floor. The pickup is the same in both windows; the magnet moves it in the
// window that owns the magnet only. A pair of windows that is not linked sends and takes nothing.
function pwrNetSend(m){
  if(typeof NET!=='object'||!NET||!NET.same||!NET.pair||typeof netSamePost!=='function') return false;
  m.t='arcpw'; m.pair=NET.pair;
  return netSamePost(m);
}
function pwrAdd(kd,x,y,gid){
  var S=pwrS(), D=pwrDef(kd);
  if(!D) return null;
  S.items.push({k:kd,x:x,y:y,t:0,life:PWR.life,id:(S.id=(S.id|0)+1),gid:gid,rem:1});
  try{ label(x,y-30,D.n,D.hex,0,true); }catch(_l){}
  try{ styTone(PWR_SND.spawn); }catch(_s){}
  return S.items[S.items.length-1];
}
function pwrNetTake(m){
  var S, i, it, D;
  if(!G||G.sim||G.over||!G.player||!(G.arcade||G.career)||!m||typeof m.gid!=='string') return 'ignored';
  S=pwrS();
  if(m.op==='new'){
    if(!pwrDef(m.k)||!isFinite(+m.x)||!isFinite(+m.y)) return 'bad';
    for(i=0;i<S.items.length;i++) if(S.items[i].gid===m.gid) return 'dup';
    if(S.items.length>=PWR.max*2) return 'full';
    pwrAdd(m.k,clamp(+m.x,0,WORLD_W),clamp(+m.y,0,WORLD_H),m.gid.slice(0,16));
    return 'new';
  }
  if(m.op==='take'){
    for(i=S.items.length-1;i>=0;i--){
      if(S.items[i].gid!==m.gid) continue;
      it=S.items[i]; D=pwrDef(it.k);
      try{ if(D) spark(it.x,it.y,D.hex,10,200); }catch(_sp){}
      S.items.splice(i,1);
      return 'take';
    }
    return 'gone';
  }
  return 'bad';
}
