{v:'VER',what:'coop9, the two player first: the power-up pickups are shared by the pair: a drop in one window is on the floor in the other, either player can take it, it is gone from both and only the one who took it has the effect',
 run:function(){
   if(!(window.__state&&window.__endRaid&&window.__runPrep)) return 'SKIP: no raid here';
   if(typeof arcadeDeploy!=='function'||typeof ARCADE!=='object'||typeof pwrDrop!=='function'||typeof pwrTick!=='function'||typeof netSameOnMsg!=='function'||typeof netSamePost!=='function') return 'SKIP: no arcade, pair channel or power-ups in this fixture';
   var bad=[], g=null, p=null, NK={}, k, oSP=netSamePost, words=[], W1=null, W2={items:[],act:{},kn:0,since:0,lastDrop:-99,drops:0,log:[],id:0}, staged=false, oIv, oSh, oAr, r, it, w;
   function as1(){ NET.same='host'; NET.seat=0; g.pwr=W1; }
   function as2(){ NET.same='p2'; NET.seat=1; g.pwr=W2; }
   try{
     __topClear(); __runPrep();
     if(ARCADE.on) return 'SKIP: the arcade is on after __topClear';
     if(!arcadeDeploy({mapIx:0,seed:4242})) return 'SKIP: arcadeDeploy built no arcade raid';
     g=__state(); if(!g||g.over||!g.player) return 'SKIP: no live raid';
     p=g.player; keys={}; oSh=p.arcSh; oAr=p.armor; oIv=p.iv; p.arcSh=0; p.armor=0; p.iv=99; ARCADE.holdT=0;
     g.ents=g.ents.filter(function(q){ return q&&(q.neutral||q.kind==='peddler'||q.kind==='stray'); });
     g.pwr=null; W1=pwrS();
     for(k in NET) NK[k]=NET[k];
     staged=true;
     NET.pair='tp';
     netSamePost=function(m){ words.push(JSON.parse(JSON.stringify(m))); return true; };
     // ONE: a pickup drops in window one: the pair is told
     as1(); words.length=0;
     pwrDrop('dmg',p.x+500,p.y);
     if(words.length!==1||words[0].t!=='arcpw'||words[0].op!=='new'||words[0].k!=='dmg') bad.push('ONE: the drop told the other window '+JSON.stringify(words));
     else {
       // TWO: window two puts the same pickup on its floor, through the real channel
       w=words[0]; as2(); r=netSameOnMsg(w);
       if(W2.items.length!==1||W2.items[0].gid!==w.gid||W2.items[0].k!=='dmg'||Math.abs(W2.items[0].x-w.x)>1) bad.push('TWO: window two has '+W2.items.length+' pickups after the word ('+r+')');
       else {
         // THREE: player two walks over it: the effect is his, and he tells window one
         words.length=0; p.x=W2.items[0].x; p.y=W2.items[0].y;
         pwrTick(p,0.05);
         if(!pwrOn('dmg')) bad.push('THREE: player two walked over the pickup and has no DOUBLE DAMAGE');
         if(W2.items.length) bad.push('THREE: the pickup is still on the floor of window two after he took it');
         if(words.length!==1||words[0].op!=='take'||words[0].gid!==w.gid) bad.push('THREE: taking the pickup told the other window '+JSON.stringify(words));
         else {
           // FOUR: window one loses the pickup and does not get the effect
           as1(); r=netSameOnMsg(words[0]);
           if(W1.items.length) bad.push('FOUR: the pickup is still on the floor of window one after player two took it ('+r+')');
           if(pwrOn('dmg')) bad.push('FOUR: window one has the effect player two took');
         }
       }
     }
     // FIVE: the other way: a pickup dropped by window two, taken by player one
     as2(); words.length=0; W2.act={};
     pwrDrop('rapid',p.x+300,p.y+40);
     if(words.length!==1||words[0].gid.charAt(1)!=='1') bad.push('FIVE: window two drop is named '+(words[0]&&words[0].gid)+', not for seat 1');
     else {
       w=words[0]; as1(); netSameOnMsg(w); words.length=0;
       if(W1.items.length!==1) bad.push('FIVE: window one has '+W1.items.length+' pickups after the word');
       else {
         p.x=W1.items[0].x; p.y=W1.items[0].y; pwrTick(p,0.05);
         if(!pwrOn('rapid')) bad.push('FIVE: player one walked over it and has no RAPID FIRE');
         as2(); netSameOnMsg(words[0]);
         if(W2.items.length) bad.push('FIVE: the pickup is still on the floor of window two after player one took it');
         if(pwrOn('rapid')) bad.push('FIVE: window two has the effect player one took');
       }
     }
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{
     netSamePost=oSP;
     if(staged){ for(k in NET) if(!(k in NK)) delete NET[k]; for(k in NK) NET[k]=NK[k]; }
     keys={};
     try{ if(g) g.pwr=null; }catch(_pw){}
     try{ if(p){ p.arcSh=oSh; p.armor=oAr; p.iv=oIv; p.hp=100; } }catch(_q){}
     try{ if(typeof ARCADE==='object'&&ARCADE.on) arcadeLeave(); }catch(_l){}
     try{ if(__state()&&!__state().over) __endRaid('abandon'); }catch(_e){}
     try{ if(typeof ARCADE==='object'){ ARCADE.mine=0; ARCADE.waveT=0; ARCADE.holdT=0; } }catch(_h){}
     __topClear();
   }
   return bad.length?bad.slice(0,8).join('; '):null; }},
